package run.iknow.mustachereact.core;

/**
 * Tags that load the frontend from a running Vite dev server instead of the built files, with hot module replacement.
 *
 * <p>Spring serves the HTML, so the tags Vite normally injects into {@code index.html} are written here: the React
 * Refresh preamble, the Vite client (HMR connection) and the generated entry module.
 */
public final class ViteDevServer {

    /** Module id of the entry generated by {@code @mustache-react/vite-plugin}, as served by the dev server. */
    static final String ENTRY_PATH = "@id/__x00__virtual:mustache-react/entry";

    private final String base;

    /**
     * @param url dev server URL including the public path, e.g. {@code http://localhost:5173/mustache-react/}
     */
    public ViteDevServer(String url) {
        this.base = url.endsWith("/") ? url : url + "/";
    }

    /**
     * @return the base URL ending with {@code /}
     */
    public String getBase() {
        return base;
    }

    /**
     * Tags for {@code <head>}: the React Refresh preamble and the Vite client. They must run before any component
     * module.
     *
     * @return HTML tags
     */
    public String headTags() {
        String escapedBase = Html.escape(base);
        return "<script type=\"module\">\n"
                + "import RefreshRuntime from \"" + jsString(base + "@react-refresh") + "\";\n"
                + "RefreshRuntime.injectIntoGlobalHook(window);\n"
                + "window.$RefreshReg$ = () => {};\n"
                + "window.$RefreshSig$ = () => (type) => type;\n"
                + "window.__vite_plugin_react_preamble_installed__ = true;\n"
                + "</script>\n"
                + "<script type=\"module\" src=\"" + escapedBase + "@vite/client\"></script>\n";
    }

    /**
     * The entry module tag, placed before {@code </body>}.
     *
     * @return HTML tag
     */
    public String scriptTags() {
        return "<script type=\"module\" src=\"" + Html.escape(base + ENTRY_PATH) + "\"></script>\n";
    }

    private static String jsString(String value) {
        StringBuilder sb = new StringBuilder();
        for (char c : value.toCharArray()) {
            if (c == '"' || c == '\\') {
                sb.append('\\').append(c);
            } else if (c == '<') {
                sb.append("\\u003c");
            } else if (c < 0x20) {
                sb.append(String.format("\\u%04x", (int) c));
            } else {
                sb.append(c);
            }
        }
        return sb.toString();
    }
}
